          </button>
          <NewTabPopover
            open={open}
            onClose={() => setOpen(false)}
            onNewTerminal={() => setOpen(false)}
            onNewBrowser={(url) => {
              setOpen(false);
              onAddBrowserTab?.(url);
            }}
            agents={agents}
            onLaunchAgent={onLaunchAgent}
            defaultAgentId={defaultAgentId}
          />
          {agents?.map((agent) => (
            <button key={agent.name} type="button" onClick={() => onLaunchAgent?.(agent)}>
              Launch {agent.name}
            </button>
          ))}
        </div>
      );
    },
  };
});
