          },
          activeLeafId: "leaf-2",
          expandedLeafId: null,
          sessionIdsByLeafId: {
            "leaf-1": "session-main-1",
            "leaf-2": "session-main-2",
          },
        },
      },
    },
    worktreeLayouts: {
